const normalize = (value: string | null | undefined) => String(value ?? "").replace(/\s+/g, " ").trim();

function translateNode(node: Node): void {
  if (node.nodeType === Node.TEXT_NODE) {
    const original = node.nodeValue ?? "";
    const normalized = normalize(original);
    const translated = ZH[normalized];
    if (translated) node.nodeValue = original.replace(normalized, translated);
    return;
  }
  if (!(node instanceof Element)) return;
  for (const attribute of ["aria-label", "title", "placeholder"]) {
    const value = node.getAttribute(attribute);
    const translated = ZH[normalize(value)];
    if (translated) node.setAttribute(attribute, translated);
  }
  const walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) translateNode(walker.currentNode);
}

export function installChineseUi(): () => void {
  translateNode(document.body);
  const observer = new MutationObserver((records) => {
    for (const record of records) {
      if (record.type === "characterData") translateNode(record.target);
      record.addedNodes.forEach(translateNode);
    }
  });
  observer.observe(document.body, { childList: true, characterData: true, subtree: true });
  return () => observer.disconnect();
}
